-- Baseline schema (generated by tools/gen_baseline.py)
CREATE TABLE app_metadata (
	id INTEGER NOT NULL, 
	"key" VARCHAR NOT NULL, 
	value VARCHAR NOT NULL, 
	CONSTRAINT pk_app_metadata PRIMARY KEY (id), 
	CONSTRAINT uq_app_metadata_key UNIQUE ("key")
);

CREATE TABLE application_records (
	id INTEGER NOT NULL, 
	customer_id INTEGER NOT NULL, 
	bill_id INTEGER, 
	application_type VARCHAR NOT NULL, 
	service_charge INTEGER NOT NULL, 
	payment_status VARCHAR NOT NULL, 
	reference_number VARCHAR, 
	application_status VARCHAR NOT NULL, 
	application_date VARCHAR NOT NULL, 
	notes VARCHAR NOT NULL, 
	CONSTRAINT pk_application_records PRIMARY KEY (id), 
	CONSTRAINT ck_application_records_charge CHECK (service_charge >= 0), 
	CONSTRAINT fk_application_records_customer_id_customers FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_application_records_bill_id_bills FOREIGN KEY(bill_id) REFERENCES bills (id) ON DELETE RESTRICT
);

CREATE TABLE audit_log (
	id INTEGER NOT NULL, 
	at VARCHAR NOT NULL, 
	action VARCHAR NOT NULL, 
	entity_type VARCHAR NOT NULL, 
	entity_id INTEGER, 
	reason VARCHAR NOT NULL, 
	details VARCHAR, 
	CONSTRAINT pk_audit_log PRIMARY KEY (id)
);

CREATE TABLE backup_history (
	id INTEGER NOT NULL, 
	file_path VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	kind VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	message VARCHAR NOT NULL, 
	CONSTRAINT pk_backup_history PRIMARY KEY (id), 
	CONSTRAINT ck_backup_history_kind CHECK (kind IN ('auto','manual','export','pre_restore','pre_migration')), 
	CONSTRAINT ck_backup_history_status CHECK (status IN ('ok','failed'))
);

CREATE TABLE bill_items (
	id INTEGER NOT NULL, 
	bill_id INTEGER NOT NULL, 
	service_id INTEGER, 
	product_id INTEGER, 
	description VARCHAR NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit VARCHAR NOT NULL, 
	unit_rate INTEGER NOT NULL, 
	amount INTEGER NOT NULL, 
	unit_cost INTEGER, 
	service_details VARCHAR, 
	CONSTRAINT pk_bill_items PRIMARY KEY (id), 
	CONSTRAINT ck_bill_items_positive CHECK (quantity > 0 AND unit_rate >= 0), 
	CONSTRAINT ck_bill_items_amount CHECK (amount = (quantity * unit_rate + 500) / 1000), 
	CONSTRAINT ck_bill_items_has_subject CHECK (service_id IS NOT NULL OR product_id IS NOT NULL OR description <> ''), 
	CONSTRAINT fk_bill_items_bill_id_bills FOREIGN KEY(bill_id) REFERENCES bills (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_bill_items_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_bill_items_product_id_products FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE RESTRICT
);

CREATE TABLE bills (
	id INTEGER NOT NULL, 
	bill_number VARCHAR NOT NULL, 
	customer_id INTEGER, 
	bill_date VARCHAR NOT NULL, 
	subtotal INTEGER NOT NULL, 
	discount INTEGER NOT NULL, 
	grand_total INTEGER NOT NULL, 
	total_paid INTEGER NOT NULL, 
	outstanding_amount INTEGER NOT NULL, 
	status VARCHAR NOT NULL, 
	notes VARCHAR NOT NULL, 
	idempotency_key VARCHAR NOT NULL, 
	cancelled_at VARCHAR, 
	cancel_reason VARCHAR, 
	created_at VARCHAR NOT NULL, 
	CONSTRAINT pk_bills PRIMARY KEY (id), 
	CONSTRAINT ck_bills_status CHECK (status IN ('unpaid','partial','paid','cancelled','refunded')), 
	CONSTRAINT ck_bills_amounts CHECK (subtotal >= 0 AND discount >= 0 AND discount <= subtotal), 
	CONSTRAINT ck_bills_grand_total CHECK (grand_total = subtotal - discount), 
	CONSTRAINT ck_bills_paid_nonneg CHECK (total_paid >= 0 AND outstanding_amount >= 0), 
	CONSTRAINT ck_bills_outstanding CHECK (status IN ('cancelled','refunded') OR outstanding_amount = grand_total - total_paid), 
	CONSTRAINT ck_bills_credit_needs_customer CHECK (outstanding_amount = 0 OR customer_id IS NOT NULL), 
	CONSTRAINT uq_bills_bill_number UNIQUE (bill_number), 
	CONSTRAINT fk_bills_customer_id_customers FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_bills_idempotency_key UNIQUE (idempotency_key)
);

CREATE TABLE customer_ledger (
	id INTEGER NOT NULL, 
	customer_id INTEGER NOT NULL, 
	transaction_type VARCHAR NOT NULL, 
	reference_type VARCHAR NOT NULL, 
	reference_id INTEGER NOT NULL, 
	debit INTEGER NOT NULL, 
	credit INTEGER NOT NULL, 
	transaction_date VARCHAR NOT NULL, 
	description VARCHAR NOT NULL, 
	CONSTRAINT pk_customer_ledger PRIMARY KEY (id), 
	CONSTRAINT ck_customer_ledger_type CHECK (transaction_type IN ('bill','payment','bill_reversal','refund','adjustment')), 
	CONSTRAINT ck_customer_ledger_one_side CHECK (debit >= 0 AND credit >= 0 AND (debit = 0 OR credit = 0)), 
	CONSTRAINT reference UNIQUE (reference_type, reference_id, transaction_type), 
	CONSTRAINT fk_customer_ledger_customer_id_customers FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE RESTRICT
);

CREATE TABLE customers (
	id INTEGER NOT NULL, 
	customer_name VARCHAR NOT NULL, 
	phone VARCHAR NOT NULL, 
	address VARCHAR, 
	notes VARCHAR NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_customers PRIMARY KEY (id)
);

CREATE TABLE daily_closings (
	id INTEGER NOT NULL, 
	closing_date VARCHAR NOT NULL, 
	expected_cash INTEGER NOT NULL, 
	counted_cash INTEGER NOT NULL, 
	difference INTEGER NOT NULL, 
	notes VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	CONSTRAINT pk_daily_closings PRIMARY KEY (id), 
	CONSTRAINT uq_daily_closings_closing_date UNIQUE (closing_date)
);

CREATE TABLE expenses (
	id INTEGER NOT NULL, 
	category VARCHAR NOT NULL, 
	description VARCHAR NOT NULL, 
	amount INTEGER NOT NULL, 
	payment_method VARCHAR NOT NULL, 
	expense_date VARCHAR NOT NULL, 
	notes VARCHAR NOT NULL, 
	is_voided BOOLEAN NOT NULL, 
	void_reason VARCHAR, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_expenses PRIMARY KEY (id), 
	CONSTRAINT ck_expenses_positive CHECK (amount > 0), 
	CONSTRAINT ck_expenses_method CHECK (payment_method IN ('cash','upi','other'))
);

CREATE TABLE inventory_transactions (
	id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	transaction_type VARCHAR NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_cost INTEGER NOT NULL, 
	reference_id INTEGER, 
	transaction_date VARCHAR NOT NULL, 
	notes VARCHAR NOT NULL, 
	CONSTRAINT pk_inventory_transactions PRIMARY KEY (id), 
	CONSTRAINT ck_inventory_transactions_type CHECK (transaction_type IN ('purchase','sale','return','adjustment','sale_reversal')), 
	CONSTRAINT ck_inventory_transactions_valid CHECK (quantity <> 0 AND unit_cost >= 0), 
	CONSTRAINT fk_inventory_transactions_product_id_products FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE RESTRICT
);

CREATE TABLE job_orders (
	id INTEGER NOT NULL, 
	job_number VARCHAR NOT NULL, 
	customer_id INTEGER NOT NULL, 
	job_description VARCHAR NOT NULL, 
	service_type VARCHAR NOT NULL, 
	total_amount INTEGER NOT NULL, 
	advance_amount INTEGER NOT NULL, 
	balance_amount INTEGER NOT NULL, 
	expected_delivery VARCHAR, 
	job_status VARCHAR NOT NULL, 
	notes VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_job_orders PRIMARY KEY (id), 
	CONSTRAINT ck_job_orders_amounts CHECK (total_amount >= 0 AND advance_amount >= 0 AND balance_amount >= 0), 
	CONSTRAINT ck_job_orders_status CHECK (job_status IN ('received','pending','in_progress','completed','delivered','cancelled')), 
	CONSTRAINT uq_job_orders_job_number UNIQUE (job_number), 
	CONSTRAINT fk_job_orders_customer_id_customers FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE RESTRICT
);

CREATE TABLE job_status_history (
	id INTEGER NOT NULL, 
	job_id INTEGER NOT NULL, 
	previous_status VARCHAR, 
	new_status VARCHAR NOT NULL, 
	changed_at VARCHAR NOT NULL, 
	notes VARCHAR NOT NULL, 
	CONSTRAINT pk_job_status_history PRIMARY KEY (id), 
	CONSTRAINT fk_job_status_history_job_id_job_orders FOREIGN KEY(job_id) REFERENCES job_orders (id) ON DELETE RESTRICT
);

CREATE TABLE lookup_values (
	id INTEGER NOT NULL, 
	kind VARCHAR NOT NULL, 
	value VARCHAR NOT NULL, 
	sort_order INTEGER NOT NULL, 
	CONSTRAINT pk_lookup_values PRIMARY KEY (id), 
	CONSTRAINT kind_value UNIQUE (kind, value)
);

CREATE TABLE payments (
	id INTEGER NOT NULL, 
	bill_id INTEGER, 
	job_id INTEGER, 
	amount INTEGER NOT NULL, 
	payment_method VARCHAR NOT NULL, 
	kind VARCHAR NOT NULL, 
	payment_date VARCHAR NOT NULL, 
	reference_number VARCHAR, 
	notes VARCHAR NOT NULL, 
	idempotency_key VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	CONSTRAINT pk_payments PRIMARY KEY (id), 
	CONSTRAINT ck_payments_positive CHECK (amount > 0), 
	CONSTRAINT ck_payments_one_target CHECK ((bill_id IS NULL) <> (job_id IS NULL)), 
	CONSTRAINT ck_payments_method CHECK (payment_method IN ('cash','upi','other')), 
	CONSTRAINT ck_payments_kind CHECK (kind IN ('payment','refund')), 
	CONSTRAINT fk_payments_bill_id_bills FOREIGN KEY(bill_id) REFERENCES bills (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_payments_job_id_job_orders FOREIGN KEY(job_id) REFERENCES job_orders (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_payments_idempotency_key UNIQUE (idempotency_key)
);

CREATE TABLE printer_settings (
	id INTEGER NOT NULL, 
	printer_name VARCHAR NOT NULL, 
	printer_type VARCHAR NOT NULL, 
	is_default BOOLEAN NOT NULL, 
	paper_size VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_printer_settings PRIMARY KEY (id), 
	CONSTRAINT name_type UNIQUE (printer_name, printer_type)
);

CREATE TABLE products (
	id INTEGER NOT NULL, 
	product_name VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	purchase_price INTEGER NOT NULL, 
	selling_price INTEGER NOT NULL, 
	stock_quantity INTEGER NOT NULL, 
	minimum_stock INTEGER NOT NULL, 
	unit VARCHAR NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_products PRIMARY KEY (id), 
	CONSTRAINT ck_products_prices CHECK (purchase_price >= 0 AND selling_price >= 0), 
	CONSTRAINT ck_products_minimum CHECK (minimum_stock >= 0), 
	CONSTRAINT uq_products_product_name UNIQUE (product_name)
);

CREATE TABLE service_rates (
	id INTEGER NOT NULL, 
	service_id INTEGER NOT NULL, 
	rate INTEGER NOT NULL, 
	effective_from VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	CONSTRAINT pk_service_rates PRIMARY KEY (id), 
	CONSTRAINT ck_service_rates_rate_nonneg CHECK (rate >= 0), 
	CONSTRAINT service_effective UNIQUE (service_id, effective_from), 
	CONSTRAINT fk_service_rates_service_id_services FOREIGN KEY(service_id) REFERENCES services (id) ON DELETE RESTRICT
);

CREATE TABLE services (
	id INTEGER NOT NULL, 
	service_name VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	billing_unit VARCHAR NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	description VARCHAR NOT NULL, 
	kind VARCHAR NOT NULL, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_services PRIMARY KEY (id), 
	CONSTRAINT ck_services_kind CHECK (kind IN ('service','stationery','custom')), 
	CONSTRAINT uq_services_service_name UNIQUE (service_name)
);

CREATE TABLE shop_settings (
	id INTEGER NOT NULL, 
	shop_name VARCHAR NOT NULL, 
	address VARCHAR NOT NULL, 
	phone VARCHAR NOT NULL, 
	email VARCHAR, 
	receipt_footer VARCHAR NOT NULL, 
	preferred_language VARCHAR NOT NULL, 
	currency VARCHAR NOT NULL, 
	default_payment_method VARCHAR NOT NULL, 
	bill_prefix VARCHAR NOT NULL, 
	receipt_show_phone BOOLEAN NOT NULL, 
	backup_dir VARCHAR, 
	owner_pin_hash VARCHAR, 
	created_at VARCHAR NOT NULL, 
	updated_at VARCHAR NOT NULL, 
	CONSTRAINT pk_shop_settings PRIMARY KEY (id), 
	CONSTRAINT ck_shop_settings_single_row CHECK (id = 1), 
	CONSTRAINT ck_shop_settings_language CHECK (preferred_language IN ('en','te'))
);

CREATE INDEX ix_audit_log_entity ON audit_log (entity_type, entity_id);

CREATE INDEX ix_bill_items_bill ON bill_items (bill_id);

CREATE INDEX ix_bills_bill_date ON bills (bill_date);

CREATE INDEX ix_bills_customer ON bills (customer_id);

CREATE INDEX ix_bills_status ON bills (status);

CREATE INDEX ix_customer_ledger_customer_date ON customer_ledger (customer_id, transaction_date);

CREATE INDEX ix_customers_name ON customers (customer_name);

CREATE INDEX ix_customers_phone ON customers (phone);

CREATE INDEX ix_expenses_date ON expenses (expense_date);

CREATE INDEX ix_inventory_transactions_product ON inventory_transactions (product_id);

CREATE INDEX ix_job_orders_status_delivery ON job_orders (job_status, expected_delivery);

CREATE INDEX ix_job_status_history_job ON job_status_history (job_id);

CREATE INDEX ix_payments_bill ON payments (bill_id);

CREATE INDEX ix_payments_date_method ON payments (payment_date, payment_method);

CREATE INDEX ix_payments_job ON payments (job_id);

CREATE INDEX ix_service_rates_service_effective ON service_rates (service_id, effective_from);
